--Settings
SafeAddString(NEW_DIALOG_ORDER_USE_ACCOUNTWIDE, "Nutze account-weite Einstellungen", 1)
SafeAddString(NEW_DIALOG_ORDER_UNREAD_TO_FRONT, "Noch nicht gewählte Optionen nach oben", 1)
SafeAddString(NEW_DIALOG_ORDER_UNREAD_TO_FRONT_DESC, "Stellt die noch nicht ausgewählten Optionen (weiße) oben über die zuvor bereits ausgewählten (grauen)", 1)
SafeAddString(NEW_DIALOG_ORDER_KEEP_CONVERSATION, "Konversation fortsetzen", 1)
SafeAddString(NEW_DIALOG_ORDER_KEEP_CONVERSATION_DESC, "Wenn du eine Gesprächsoption wählst, werden die darauf folgenden Dialogoptionen, die vom Spiel als Fortsetzung des Gesprächs behandelt werden, nach oben verschoben, sogar über priorisierte Optionen (Bank, Laden, etc.). Dies ermöglicht einen natürlichen Gesprächsfluss, bei dem Bank-/Ladenoptionen nicht in die Quere kommen, wenn du bewusst ein bestimmtes Thema ansprichst.", 1)
SafeAddString(NEW_DIALOG_ORDER_CUSTOMIZE, "Reihenfolge anpassen", 1)
SafeAddString(NEW_DIALOG_ORDER_CUSTOMIZE_DESC, "Standardmäßig ändert das Addon die Reihenfolge funktionaler Dialogoptionen nicht. Nur deren Reihenfolge im Verhältnis zu den anderen – konversationellen – Optionen.\nWenn ein Bank-NPC 'Bank', 'Gildenbank' und dann 'Gildenladen' anbietet, werden diese Optionen in derselben Reihenfolge in der Liste nach oben verschoben.\nWenn 'Gildenbank' vor der 'Bank' stehen soll, aktiviere diese Option und richte deine benutzerdefinierte Prioritätsreihenfolge im Menü unten ein.", 1)
SafeAddString(NEW_DIALOG_ORDER_PRIORITY_ORDER, "Prioritäts-Sortierung", 1)
SafeAddString(NEW_DIALOG_ORDER_UNMANAGED, "Standardreihenfolge", 1)
SafeAddString(NEW_DIALOG_ORDER_MANAGE_DESC, "Einstellung der Priorität von Optionen in Dialogen.\n‚Standardreihenfolge‘ bedeutet, dass die Option als normale Gesprächsoption behandelt und nicht nach oben verschoben wird.", 1)

